<?php
function bizQtyGrid(array $products,array $items,bool $readonly=false): void { ?>
<div class="biz-order-grid" data-biz-qty-grid><?php foreach(bizCategories() as $key=>$label):$group=array_filter($products,fn($p)=>$p['category']===$key);if(!$group)continue; ?><section class="biz-quantity-category"><h3><?=$label?> <span class="biz-category-total" data-biz-total>0개</span></h3><div class="biz-quantity-rows"><?php foreach($group as $p): ?><label><span><?=e(bizKo($p))?></span><input aria-label="<?=e(bizKo($p))?> 수량" name="qty[<?=$p['id']?>]" type="number" inputmode="numeric" min="0" max="10000" value="<?=(int)($items[$p['id']]??0)?>" <?=$readonly?'readonly':''?>></label><?php endforeach ?></div></section><?php endforeach ?><p class="biz-quantity-grand-total">총 주문 수량 <strong data-biz-grand-total>0개</strong></p></div>
<?php }
if($page==='biz-plan'||$page==='biz-deliveries'):
 $ordersPage=$page==='biz-plan';$date=$ordersPage?validDate($_GET['day']??$today):((($_GET['day']??'')==='')?'':validDate($_GET['day']));
 $docs=query('SELECT o.*,c.name,(SELECT COUNT(*) FROM biz_deliveries d WHERE d.batch_key=o.batch_key AND d.sent=1) sent,(SELECT COUNT(*) FROM biz_deliveries d WHERE d.batch_key=o.batch_key AND d.cancelled=0 AND d.sent=0) pending FROM biz_orders o JOIN biz_clients c ON c.id=o.client_id WHERE o.cancelled=0'.($date!==''?($ordersPage?' AND o.order_date=?':' AND o.day=?'):'').' ORDER BY o.day DESC,o.batch_key DESC',$date!==''?[$date]:[])->fetchAll(); ?>
<div class="toolbar"><?php if($ordersPage): ?><a href="/?page=biz-order" class="button">주문서 입력</a><?php endif ?></div>
<form method="get" class="biz-inline"><input type="hidden" name="page" value="<?=e($page)?>"><label><?=$ordersPage?'주문서 작성일':'납품 예정일'?><input type="date" name="day" value="<?=e($date)?>" <?=$ordersPage?'required':''?>></label><button class="button secondary">보기</button><?php if(!$ordersPage): ?><a href="/?page=biz-deliveries">전체 납품서</a><?php endif ?></form>
<section class="panel biz-compact"><h2 class="biz-small-heading"><?=$ordersPage?e($date).' 주문서 내역':'납품서 내역'?> · <?=count($docs)?>건</h2><?php if(!$docs): ?><p>표시할 <?=$ordersPage?'주문서':'납품서'?>가 없습니다.</p><?php endif ?>
<?php foreach($docs as $o):$lines=query('SELECT d.*,p.ko,p.pack FROM biz_deliveries d JOIN biz_products p ON p.id=d.product_id WHERE d.batch_key=? AND d.cancelled=0 ORDER BY p.id',[$o['batch_key']])->fetchAll();$locked=$o['manual_edited']||$o['sent']; ?>
<article class="biz-document-row"><div class="biz-document-title"><a href="/?page=<?=$ordersPage?'biz-order':'biz-delivery'?>&amp;batch=<?=$o['batch_key']?>"><?=e($o['name'])?></a><span>납품 <?=e($ordersPage?$o['order_day']:$o['day'])?></span><span class="badge <?=$o['sent']&&!$o['pending']?'done':''?>"><?=$o['sent']?($o['pending']?'일부 납품':'납품 완료'):($o['manual_edited']?'납품서 수정됨':'납품 전')?></span></div><div class="biz-document-items"><?php if($ordersPage):$original=json_decode($o['items'],true);foreach($products as $p){if(!empty($original[$p['id']]))echo '<span class="badge">'.e(bizKo($p)).' '.(int)$original[$p['id']].'</span>';}else:foreach($lines as $line): ?><span class="badge"><?=e(bizKo($line))?> <?=$line['sent']?$line['delivered']:$line['planned']?></span><?php endforeach;endif ?></div><div class="biz-row-actions"><?php if($ordersPage&&!$locked): ?><form method="post"><?=csrf()?><input type="hidden" name="action" value="biz_order_delete"><input type="hidden" name="batch_key" value="<?=$o['batch_key']?>"><input type="hidden" name="version" value="<?=$o['version']?>"><button class="button danger biz-trash" aria-label="<?=e($o['name'])?> 주문서 삭제" data-confirm="주문서와 연결된 납품서를 함께 삭제할까요?">&#128465;</button></form><?php elseif(!$ordersPage): ?><a class="button secondary" href="/?page=biz-document-print&amp;batch=<?=$o['batch_key']?>">인보이스 보기·인쇄</a><?php endif ?></div></article>
<?php endforeach ?></section>
<?php elseif($page==='biz-order'||$page==='biz-delivery'):
 $deliveryPage=$page==='biz-delivery';$key=(string)($_GET['batch']??'');$o=$key!==''?bizBatch($key):null;if($deliveryPage&&!$o)throw new InvalidArgumentException('납품서를 선택하세요.');$sent=$o&&bizBatchSent($key);$pending=$o&&bizBatchPending($key);$locked=$deliveryPage?$sent:($o&&($o['manual_edited']||$sent));$items=$o?json_decode($o['items'],true):[];
 if($deliveryPage){$items=[];foreach(query('SELECT product_id,planned,delivered,sent FROM biz_deliveries WHERE batch_key=? AND cancelled=0',[$key])->fetchAll() as $line)$items[$line['product_id']]=(int)($line['sent']?$line['delivered']:$line['planned']);}
 ?>
<div class="toolbar"><a href="/?page=<?=$deliveryPage?'biz-deliveries':'biz-plan'?>">← <?=$deliveryPage?'납품서':'주문서'?> 목록으로</a><?php if($o): ?><a class="button secondary" href="/?page=biz-document-print&amp;batch=<?=$key?>">인보이스 보기·인쇄</a><?php endif ?></div>
<?php if($locked): ?><p class="notice"><?=$deliveryPage?($pending?'일부 품목이 이미 납품되었습니다. 납품된 수량을 보존하며 남은 품목은 아래에서 납품 확정할 수 있습니다.':'납품 완료된 문서입니다. 수량과 금액을 보존합니다.'):'납품서를 직접 수정했거나 납품 완료하여 이 주문서는 수정·삭제할 수 없습니다.'?><?php if(!$deliveryPage): ?> <a href="/?page=biz-delivery&amp;batch=<?=$key?>">납품서 확인</a><?php endif ?></p><?php endif ?>
<form method="post" class="panel stack biz-order-form"><?=csrf()?><?php if(!$deliveryPage): ?><input type="hidden" name="action" value="biz_order_save"><?php endif ?><input type="hidden" name="batch_key" value="<?=e($key)?>"><input type="hidden" name="version" value="<?=(int)($o['version']??0)?>"><input type="hidden" name="request_key" value="<?=bin2hex(random_bytes(16))?>">
<fieldset <?=$locked?'disabled':''?>><div class="biz-order-fields"><label>거래처<select name="client_id" <?=$deliveryPage?'disabled':''?> required><option value="">거래처 선택</option><?php foreach($clients as $c): ?><option value="<?=$c['id']?>" <?=($o&&(int)$o['client_id']===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach ?></select></label><label>납품 예정일<input name="day" type="date" value="<?=e($o?($deliveryPage?$o['day']:$o['order_day']):date('Y-m-d',strtotime('tomorrow')))?>" required></label><label>할인율 (%)<input name="discount" type="number" min="0" max="100" step=".01" value="<?=($o?($deliveryPage?$o['discount_bp']:$o['order_discount_bp']):0)/100?>" required></label><label class="biz-order-notes">비고<input name="notes" maxlength="2000" value="<?=e($o?($deliveryPage?$o['document_notes']:$o['notes']):'')?>"></label></div>
<?php bizQtyGrid($products,$items,$locked); ?><?php if(!$locked): ?><div class="biz-row-actions"><?php if($deliveryPage): ?><button name="action" value="biz_document_save" class="button secondary">납품서 저장</button><button name="action" value="biz_document_confirm" class="button" data-confirm="화면에 입력한 수량으로 저장하고 납품 완료할까요? 완료 후 납품서 수정은 잠깁니다.">납품 완료</button><?php else: ?><button class="button">주문서 저장</button><?php endif ?></div><?php endif ?></fieldset></form>
<?php if($deliveryPage&&$pending&&$sent): ?><form method="post" class="panel biz-inline"><?=csrf()?><input type="hidden" name="action" value="biz_document_confirm"><input type="hidden" name="batch_key" value="<?=$key?>"><input type="hidden" name="version" value="<?=$o['version']?>"><span>저장된 수량대로 납품을 확정합니다.</span><button class="button" data-confirm="저장된 수량으로 납품 완료할까요? 완료 후 납품서 수정은 잠깁니다.">납품 완료</button></form><?php endif ?>
<?php elseif($page==='biz-document-print'):
 $o=bizBatch((string)($_GET['batch']??''));$c=query('SELECT * FROM biz_clients WHERE id=?',[$o['client_id']])->fetch();$seller=query('SELECT * FROM biz_settings WHERE id=1')->fetch();
 $existing=query('SELECT DISTINCT i.id,i.issued FROM biz_invoices i JOIN biz_sales s ON s.invoice_id=i.id JOIN biz_deliveries d ON d.id=s.delivery_id WHERE d.batch_key=? ORDER BY i.id',[$o['batch_key']])->fetchAll();
 $lines=query('SELECT p.*,d.planned,d.delivered,d.sent FROM biz_deliveries d JOIN biz_products p ON p.id=d.product_id WHERE d.batch_key=? AND d.cancelled=0 ORDER BY p.id',[$o['batch_key']])->fetchAll();$net=$taxable=$tax=0;$complete=true;$preview=[];
 foreach($lines as $p){$qty=$p['sent']?(int)$p['delivered']:(int)$p['planned'];try{$unit=bizPrice($c,$p);}catch(InvalidArgumentException){$unit=null;}$known=$unit!==null&&$p['hst_bp']!==null;$complete=$complete&&$known;$bp=$c['code']==='OK'&&$p['category']!=='kimchi'?2000:(int)$o['discount_bp'];$cut=$unit===null?null:(int)round($qty*$unit*$bp/10000);$amount=$unit===null?null:$qty*$unit-$cut;$lineTax=null;if($known){$net+=$amount;if((int)$p['hst_bp']>0){$taxable+=$amount;$next=(int)round($taxable*13/100);$lineTax=$next-$tax;$tax=$next;}else $lineTax=0;}$preview[]=[...$p,'qty'=>$qty,'unit'=>$unit,'cut'=>$cut,'amount'=>$amount,'tax'=>$lineTax];}
 ?>
<div class="toolbar no-print"><a href="/?page=biz-delivery&amp;batch=<?=$o['batch_key']?>">← 납품서로</a><button class="button" id="print-order" type="button">인쇄 / PDF 저장</button><?php foreach($existing as $i): ?><a class="button secondary" href="/?page=biz-invoice&amp;id=<?=$i['id']?>">발행된 인보이스 RN<?=$i['id']?></a><?php endforeach ?></div>
<p class="notice no-print">납품 수량·금액 확인용입니다. 실제 청구 인보이스는 직매출 납품 완료 또는 위탁판매 정산 시 발행됩니다.<?php if(!$complete): ?> 단가·HST가 미등록된 상품을 먼저 확인하세요.<?php endif ?></p>
<section class="panel biz-invoice"><h2><?=e($seller['seller'])?> · PRO FORMA INVOICE</h2><p><?=e($seller['address'])?> · GST/HST <?=e($seller['gst'])?></p><p>Bill To: <?=e($c['name'].' · '.$c['address'])?></p><p>Delivery Date: <?=e($o['day'])?> · Ref: <?=e(substr($o['batch_key'],0,8))?></p><table><thead><tr><th>Product</th><th>Qty</th><th>Unit</th><th>Discount</th><th>Net</th><th>HST</th></tr></thead><tbody><?php foreach($preview as $l): ?><tr><td><?=e(bizLabel($l))?></td><td><?=$l['qty']?></td><td><?=$l['unit']===null?'미등록':money($l['unit'])?></td><td><?=$l['cut']===null?'—':money($l['cut'])?></td><td><?=$l['amount']===null?'—':money($l['amount'])?></td><td><?=$l['tax']===null?'확인 필요':money($l['tax'])?></td></tr><?php endforeach ?></tbody></table><?php if($complete): ?><p>Subtotal <?=money($net)?> · HST <?=money($tax)?> · <strong>Total <?=money($net+$tax)?></strong></p><?php else: ?><p>가격·세율 등록이 끝나면 총금액이 표시됩니다.</p><?php endif ?><?php if($o['document_notes']): ?><p><?=e($o['document_notes'])?></p><?php endif ?><p>PRO FORMA · Not a tax invoice · 실제 청구 전 확인용</p></section>
<?php endif ?>
